cat > tests/services/zz-scratch-suspend.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberService from "@/server/services/member-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as commentService from "@/server/services/comment-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers?.(); });
afterAll(() => cleanup());

describe("suspend", () => {
  it("works end to end", async () => {
    const t = await createTenant("susp", "growth");
    const m = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    const o = (await memberRepo.findMember(t.org.id, t.userIds.owner))!;
    const events: string[] = [];
    subscribe("member.suspended", () => { events.push("s"); });
    await expect(memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: o.id })).rejects.toThrow();
    await expect(memberService.suspendMember(t.actors.owner, { orgId: t.org.id, memberId: o.id })).rejects.toThrow();
    const s = await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: m.id });
    expect(s.status).toBe("suspended");
    await memberService.suspendMember(t.actors.admin, { orgId: t.org.id, memberId: m.id });
    expect(events).toEqual(["s"]);
    expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toBeNull();
    expect(await orgRepo.listOrgsForUser(t.userIds.member)).toEqual([]);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    await expect(issueService.createIssue(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, title: "abc", assigneeId: t.userIds.member } as never)).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    expect(await notificationService.notify(t.org.id, "issue_assigned", [t.userIds.member], { title: "x", body: "y", href: "/", actorId: null })).toEqual([]);
    const issue = await issueService.createIssue(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, title: "abc", assigneeId: null } as never);
    await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    const c = await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "hi", mentionedUserIds: [t.userIds.member, t.userIds.viewer] } as never);
    expect(c.mentionedUserIds).toEqual([t.userIds.viewer]);
    const r = await memberService.reinstateMember(t.actors.admin, { orgId: t.org.id, memberId: m.id });
    expect(r.status).toBe("active");
    const page = await activityRepo.listActivity({ orgId: t.org.id, action: ["member.suspended", "member.reinstated"], limit: 10, cursor: null } as never);
    expect(page.items.map((e) => e.action).sort()).toEqual(["member.reinstated", "member.suspended"]);
  });
});
EOF
